-- Каталог из согласованного макета Figma; цены в тенге.
-- Повторный запуск не изменяет услуги, которые мастер уже отредактировал.
insert into public.services
  (id, category, name, description, price, duration_minutes, sort_order)
values
  ('d883f62e-44a8-4380-b0d0-a2dd4ec45c67', 'lashes', 'Классическое наращивание', 'Один искусственный ресничный волосок крепится к одной натуральной ресничке. Натуральный эффект, идеально для повседневного образа.', 14980, 120, 1),
  ('54a82720-0915-4705-85fa-c83052db3b5a', 'lashes', '2D / 3D объём', 'Два-три волоска в веере на одну реснику. Объёмный, выразительный взгляд без утяжеления.', 18725, 150, 2),
  ('4aec2b43-f615-4864-b8e1-e899471415e1', 'lashes', 'Голливудский объём', 'Максимальный объём и плотность. Роскошный вечерний эффект, модный и очень женственный.', 22470, 180, 3),
  ('9c9b6691-59db-465b-a694-b79518b3c1c1', 'lashes', 'Ламинирование ресниц', 'Придаёт ресницам форму, изгиб и ухоженный вид без наращивания. Эффект держится до 6 недель.', 11770, 60, 4),
  ('07f8e7e4-41bd-465b-bd5b-f11a9b0f7c65', 'lashes', 'Коррекция (через 3–4 нед.)', 'Заполнение выпавших ресничек, восстановление формы и объёма. Обязательна раз в 3–4 недели.', 9630, 90, 5),
  ('72f38d85-d7b0-47a6-b9a7-ea55e68ef697', 'lashes', 'Снятие ресниц', 'Безопасное и безболезненное снятие нарощенных ресниц специальным составом. Без ущерба для натуральных.', 2675, 30, 6),
  ('e58c75ed-8fc5-4d06-9a5b-73a7ee8c8eaf', 'brows', 'Архитектура бровей', 'Придание идеальной формы с учётом анатомии лица и пожеланий клиента. Коррекция воском и нитью.', 8025, 60, 1),
  ('d349a74d-edfe-434a-9dca-185a9f3768b7', 'brows', 'Окрашивание хной', 'Стойкое окрашивание натуральной хной. Придаёт насыщенный цвет и визуально заполняет редкие участки.', 6420, 60, 2),
  ('b24d3811-31f8-482f-9d85-cd010aedf502', 'brows', 'Ламинирование бровей', 'Укладка и ламинирование бровей. Густой, ухоженный вид на 4–6 недель без лишних усилий каждое утро.', 9630, 60, 3),
  ('b7980ecf-7bba-4bde-ad7c-44c19c7e1215', 'brows', 'Коррекция бровей', 'Поддерживающая коррекция формы. Подходит тем, кто уже поставил форму и хочет её поддерживать.', 3745, 30, 4)
on conflict (id) do nothing;

